From 447e83f94d8242665497317ab22e509324b56741 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:47:32 +0100
Subject: [PATCH] applet: show the hovered volume in a tooltip over the slider

Choosing a precise volume with the mouse meant guessing where to click,
since the slider only shows its current value. A tooltip now follows the
pointer while hovering and shows the volume that a click there would set.

BUG: 526809
---
 applet/VolumeSlider.qml | 21 +++++++++++++++++++++
 1 file changed, 21 insertions(+)

diff --git a/applet/VolumeSlider.qml b/applet/VolumeSlider.qml
index 5f365ccb..96b4656e 100644
--- a/applet/VolumeSlider.qml
+++ b/applet/VolumeSlider.qml
@@ -91,6 +91,27 @@ PC3.Slider {
         }     
     }

+    HoverHandler {
+        id: hoverHandler
+    }
+
+    PC3.ToolTip {
+        readonly property real hoveredPosition: {
+            const handleSize = control.horizontal ? control.handle.width : control.handle.height;
+            const pos = control.horizontal
+                ? (hoverHandler.point.position.x - control.leftPadding - handleSize / 2) / (control.availableWidth - handleSize)
+                : 1 - (hoverHandler.point.position.y - control.topPadding - handleSize / 2) / (control.availableHeight - handleSize);
+            const clamped = Math.max(0, Math.min(1, pos));
+            return control.horizontal && control.mirrored ? 1 - clamped : clamped;
+        }
+
+        x: control.horizontal ? Math.round(hoverHandler.point.position.x - width / 2) : control.width
+        y: control.horizontal ? -height - Kirigami.Units.smallSpacing : Math.round(hoverHandler.point.position.y - height / 2)
+        visible: hoverHandler.hovered && !control.pressed && control.enabled
+        delay: Kirigami.Units.toolTipDelay
+        text: i18nc("volume percentage", "%1%", Math.round(control.valueAt(hoveredPosition) / PulseAudio.NormalVolume * 100))
+    }
+
     background: KSvg.FrameSvgItem {
         imagePath: "widgets/slider"
         prefix: "groove"
-- 
